-- M4 additive publications. Legacy snapshots/heads/rows are not rewritten or republished.
DO $$ BEGIN IF current_user<>'gcms_s02_owner' OR NOT EXISTS(SELECT 1 FROM pg_namespace WHERE nspname='gcms_m4' AND nspowner=(SELECT oid FROM pg_roles WHERE rolname='gcms_s02_owner')) THEN RAISE EXCEPTION 'M4 pre-owned namespace required';END IF;END $$;
REVOKE ALL ON SCHEMA gcms_m4 FROM PUBLIC;
CREATE FUNCTION gcms_m4.locale(v text) RETURNS boolean LANGUAGE sql IMMUTABLE SET search_path=pg_catalog AS $$ SELECT coalesce(v IN ('vi','en'),false) $$;
CREATE FUNCTION gcms_m4.kind(v text) RETURNS boolean LANGUAGE sql IMMUTABLE SET search_path=pg_catalog AS $$ SELECT coalesce(v IN ('home','page','landing','promotion','service','config') OR gcms_m3.kind(v),false) $$;
CREATE FUNCTION gcms_m4.text(v jsonb,n integer,required boolean DEFAULT false) RETURNS boolean LANGUAGE sql IMMUTABLE SET search_path=pg_catalog AS $$ SELECT coalesce(jsonb_typeof(v)='string' AND length(v#>>'{}')<=n AND (NOT required OR length(btrim(v#>>'{}'))>0),false) $$;
CREATE FUNCTION gcms_m4.page_slug(s text) RETURNS boolean LANGUAGE sql IMMUTABLE SET search_path=pg_catalog AS $$ SELECT gcms_s02.valid_slug(s) AND s<>ALL(ARRAY['home','landing','khuyen-mai','sitemap','robots','sitemap-xml','favicon','chuyen-khoa','nhom-dich-vu','co-so','bac-si','bang-gia','ca-dieu-tri','truoc-sau','danh-gia','bai-viet','chuyen-muc','hoi-dap']) $$;
CREATE FUNCTION gcms_m4.target(v jsonb) RETURNS boolean LANGUAGE sql IMMUTABLE SET search_path=pg_catalog AS $$ SELECT coalesce(jsonb_typeof(v)='object' AND v ?& ARRAY['kind','id','locale'] AND (v-ARRAY['kind','id','locale'])='{}' AND gcms_m4.kind(v->>'kind') AND v->>'kind'<>'config' AND gcms_m3.uuid(v->>'id') AND gcms_m4.locale(v->>'locale'),false) $$;
CREATE FUNCTION gcms_m4.image(v jsonb) RETURNS boolean LANGUAGE sql IMMUTABLE SET search_path=pg_catalog AS $$ SELECT coalesce(v='null'::jsonb OR (jsonb_typeof(v)='object' AND v ?& ARRAY['assetId','revision','alt'] AND (v-ARRAY['assetId','revision','alt'])='{}' AND gcms_m3.uuid(v->>'assetId') AND gcms_m3.version(v->'revision') AND gcms_m4.text(v->'alt',500,true)),false) $$;
CREATE FUNCTION gcms_m4.promotion_ref(v jsonb) RETURNS boolean LANGUAGE sql IMMUTABLE SET search_path=pg_catalog AS $$ SELECT coalesce(jsonb_typeof(v)='object' AND v ?& ARRAY['kind','id','publicationId'] AND (v-ARRAY['kind','id','publicationId'])='{}' AND v->>'kind'='promotion' AND gcms_m3.uuid(v->>'id') AND gcms_m3.uuid(v->>'publicationId'),false) $$;
CREATE FUNCTION gcms_m4.valid_content(k text,c jsonb) RETURNS boolean LANGUAGE plpgsql IMMUTABLE SET search_path=pg_catalog AS $$
DECLARE s jsonb;i jsonb;ref jsonb;seen text[]:='{}';allowed text[];extra text[];forms integer:=0;BEGIN
 IF gcms_m4.kind(k) IS NOT TRUE OR jsonb_typeof(c) IS DISTINCT FROM 'object' OR octet_length(c::text)>524288 THEN RETURN false;END IF;
 IF gcms_m3.kind(k) THEN RETURN gcms_m3.valid_content(c) IS TRUE AND c->>'kind'=k;END IF;
 IF k='config' THEN
  IF NOT(c ?& ARRAY['name','logo','theme','themeVersion','palette','font','layout','footer','menu']) OR (c-ARRAY['name','logo','theme','themeVersion','palette','font','layout','footer','menu'])<>'{}' OR NOT gcms_m4.text(c->'name',160,true) OR NOT gcms_m4.image(c->'logo') OR coalesce(c->>'theme','') NOT IN ('clarity','showcase') OR c->'themeVersion' IS DISTINCT FROM '1'::jsonb OR coalesce(c->>'palette','') NOT IN ('teal','blue','plum') OR coalesce(c->>'font','') NOT IN ('system','serif') OR coalesce(c->>'layout','') NOT IN ('comfortable','compact') OR jsonb_typeof(c->'footer') IS DISTINCT FROM 'object' OR NOT(c->'footer' ?& ARRAY['intro','body']) OR ((c->'footer')-ARRAY['intro','body'])<>'{}' OR NOT gcms_m4.text(c->'footer'->'intro',500) OR gcms_s02.valid_document(c->'footer'->'body',2000) IS NOT TRUE OR jsonb_typeof(c->'menu') IS DISTINCT FROM 'array' OR jsonb_array_length(c->'menu')>20 THEN RETURN false;END IF;
  FOR i IN SELECT value FROM jsonb_array_elements(c->'menu') LOOP IF jsonb_typeof(i) IS DISTINCT FROM 'object' OR NOT(i ?& ARRAY['id','label','target','allowViFallback']) OR (i-ARRAY['id','label','target','allowViFallback'])<>'{}' OR i->>'id' !~ '^[-a-zA-Z0-9_]{1,64}$' OR i->>'id'=ANY(seen) OR NOT gcms_m4.text(i->'label',80,true) OR NOT gcms_m4.target(i->'target') OR jsonb_typeof(i->'allowViFallback') IS DISTINCT FROM 'boolean' THEN RETURN false;END IF;seen:=array_append(seen,i->>'id');END LOOP;RETURN true;
 END IF;
 IF NOT(c ?& ARRAY['slug','title','summary','seo']) OR gcms_s02.valid_slug(c->>'slug') IS NOT TRUE OR NOT gcms_m4.text(c->'title',160,true) OR NOT gcms_m4.text(c->'summary',320) OR jsonb_typeof(c->'seo') IS DISTINCT FROM 'object' OR NOT(c->'seo' ?& ARRAY['title','description']) OR ((c->'seo')-ARRAY['title','description'])<>'{}' OR NOT gcms_m4.text(c->'seo'->'title',160) OR NOT gcms_m4.text(c->'seo'->'description',320) THEN RETURN false;END IF;
 IF k='service' THEN
  IF NOT(c ? 'body') OR (c-ARRAY['slug','title','summary','seo','body','coverImage','contentLinks'])<>'{}' OR gcms_s02.valid_document(c->'body',20000) IS NOT TRUE OR (c ? 'coverImage' AND NOT gcms_m4.image(c->'coverImage')) THEN RETURN false;END IF;
  IF c ? 'contentLinks' THEN IF jsonb_typeof(c->'contentLinks') IS DISTINCT FROM 'object' OR NOT(c->'contentLinks' ? 'references') OR ((c->'contentLinks')-'references')<>'{}' OR NOT gcms_m3.references_shape(c->'contentLinks'->'references') THEN RETURN false;END IF;FOR ref IN SELECT value FROM jsonb_array_elements(c->'contentLinks'->'references') LOOP IF ref->>'kind'<>ALL(ARRAY['specialty','service_group','location','service','faq']) THEN RETURN false;END IF;END LOOP;END IF;RETURN true;
 END IF;
 IF c->>'kind' IS DISTINCT FROM k THEN RETURN false;END IF;
 IF k='promotion' THEN
  IF NOT(c ?& ARRAY['kind','body','startAt','endAt','authoredTimezone','conditions','references']) OR (c-ARRAY['kind','slug','title','summary','seo','body','startAt','endAt','authoredTimezone','conditions','references'])<>'{}' OR gcms_s02.valid_document(c->'body',20000) IS NOT TRUE OR NOT gcms_m4.text(c->'conditions',5000,true) OR NOT gcms_m4.text(c->'authoredTimezone',80,true) OR c->>'startAt' !~ '^\d{4}-\d\d-\d\dT\d\d:\d\d:\d\d\.\d{3}Z$' OR c->>'endAt' !~ '^\d{4}-\d\d-\d\dT\d\d:\d\d:\d\d\.\d{3}Z$' OR (c->>'startAt')::timestamptz>=(c->>'endAt')::timestamptz OR NOT EXISTS(SELECT 1 FROM pg_timezone_names WHERE name=c->>'authoredTimezone') OR NOT gcms_m3.references_shape(c->'references') THEN RETURN false;END IF;
  FOR ref IN SELECT value FROM jsonb_array_elements(c->'references') LOOP IF ref->>'kind'<>ALL(ARRAY['service','location','price']) THEN RETURN false;END IF;END LOOP;RETURN true;
 END IF;
 IF NOT(c ?& ARRAY['kind','sections']) OR (c-ARRAY['kind','slug','title','summary','seo','sections'])<>'{}' OR jsonb_typeof(c->'sections') IS DISTINCT FROM 'array' OR jsonb_array_length(c->'sections')>30 OR (k='home' AND c->>'slug'<>'home') OR (k='page' AND NOT gcms_m4.page_slug(c->>'slug')) THEN RETURN false;END IF;
 FOR s IN SELECT value FROM jsonb_array_elements(c->'sections') LOOP
  IF jsonb_typeof(s) IS DISTINCT FROM 'object' OR NOT(s ?& ARRAY['id','type','hidden']) OR s->>'id' !~ '^[-a-zA-Z0-9_]{1,64}$' OR s->>'id'=ANY(seen) OR jsonb_typeof(s->'hidden') IS DISTINCT FROM 'boolean' THEN RETURN false;END IF;seen:=array_append(seen,s->>'id');
  extra:=CASE s->>'type' WHEN 'hero' THEN ARRAY['title','text','image','action'] WHEN 'rich_text' THEN ARRAY['body'] WHEN 'promotion' THEN ARRAY['title','reference','required'] WHEN 'consultation' THEN ARRAY['title','promotion','serviceOptions','locationOptions'] ELSE ARRAY['title','references','required'] END;
  IF NOT(s ?& extra) OR (s-(ARRAY['id','type','hidden']||extra))<>'{}' THEN RETURN false;END IF;
  IF s->>'type'='hero' THEN
   IF NOT gcms_m4.text(s->'title',160,true) OR NOT gcms_m4.text(s->'text',1000) OR NOT gcms_m4.image(s->'image') THEN RETURN false;END IF;
   i:=s->'action';IF i<>'null'::jsonb AND (jsonb_typeof(i) IS DISTINCT FROM 'object' OR NOT(i ?& ARRAY['label','target','allowViFallback']) OR (i-ARRAY['label','target','allowViFallback'])<>'{}' OR NOT gcms_m4.text(i->'label',80,true) OR NOT gcms_m4.target(i->'target') OR jsonb_typeof(i->'allowViFallback') IS DISTINCT FROM 'boolean') THEN RETURN false;END IF;
  ELSIF s->>'type'='rich_text' THEN IF gcms_s02.valid_document(s->'body',20000) IS NOT TRUE THEN RETURN false;END IF;
  ELSIF s->>'type'='promotion' THEN IF NOT gcms_m4.text(s->'title',160) OR NOT gcms_m4.promotion_ref(s->'reference') OR jsonb_typeof(s->'required') IS DISTINCT FROM 'boolean' THEN RETURN false;END IF;
  ELSIF s->>'type'='consultation' THEN
   forms:=forms+1;IF forms>1 OR k<>'landing' OR NOT gcms_m4.text(s->'title',160) OR (s->'promotion'<>'null'::jsonb AND NOT gcms_m4.promotion_ref(s->'promotion')) OR NOT gcms_m3.references_shape(s->'serviceOptions') OR NOT gcms_m3.references_shape(s->'locationOptions') THEN RETURN false;END IF;
   FOR ref IN SELECT value FROM jsonb_array_elements(s->'serviceOptions') LOOP IF ref->>'kind'<>'service' THEN RETURN false;END IF;END LOOP;FOR ref IN SELECT value FROM jsonb_array_elements(s->'locationOptions') LOOP IF ref->>'kind'<>'location' THEN RETURN false;END IF;END LOOP;
  ELSE
   allowed:=CASE s->>'type' WHEN 'services' THEN ARRAY['service','specialty','service_group'] WHEN 'doctors' THEN ARRAY['doctor'] WHEN 'locations' THEN ARRAY['location'] WHEN 'prices' THEN ARRAY['price'] WHEN 'cases' THEN ARRAY['case'] WHEN 'gallery' THEN ARRAY['gallery'] WHEN 'testimonials' THEN ARRAY['testimonial'] WHEN 'articles' THEN ARRAY['article'] WHEN 'faq' THEN ARRAY['faq'] END;
   IF allowed IS NULL OR NOT gcms_m4.text(s->'title',160) OR NOT gcms_m3.references_shape(s->'references') OR jsonb_array_length(s->'references')>30 OR jsonb_typeof(s->'required') IS DISTINCT FROM 'boolean' THEN RETURN false;END IF;FOR ref IN SELECT value FROM jsonb_array_elements(s->'references') LOOP IF NOT(ref->>'kind'=ANY(allowed)) THEN RETURN false;END IF;END LOOP;
  END IF;
 END LOOP;RETURN true;
EXCEPTION WHEN OTHERS THEN RETURN false;END $$;
CREATE TABLE gcms_m4.identity(tenant_id text NOT NULL REFERENCES gcms_s02.tenant(id),id text NOT NULL CHECK(gcms_m3.uuid(id)),kind text NOT NULL CHECK(kind IN ('home','page','landing','promotion')),slug text NOT NULL,slug_locked boolean NOT NULL DEFAULT false,PRIMARY KEY(tenant_id,kind,id),UNIQUE(tenant_id,kind,slug),CHECK((kind='home' AND slug='home') OR (kind='page' AND gcms_m4.page_slug(slug)) OR (kind IN ('landing','promotion') AND gcms_s02.valid_slug(slug))));
CREATE TABLE gcms_m4.variant(tenant_id text NOT NULL REFERENCES gcms_s02.tenant(id),kind text NOT NULL CHECK(gcms_m4.kind(kind)),resource_id text NOT NULL CHECK(gcms_m3.uuid(resource_id)),locale text NOT NULL CHECK(gcms_m4.locale(locale)),version integer NOT NULL CHECK(version>0),content jsonb NOT NULL,publication_version integer NOT NULL DEFAULT 0 CHECK(publication_version>=0),publication_revision integer NOT NULL DEFAULT 0 CHECK(publication_revision>=0),generation integer NOT NULL DEFAULT 0 CHECK(generation>=0),legacy_guard jsonb,active_publication_id text,updated_by text NOT NULL,updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),PRIMARY KEY(tenant_id,kind,resource_id,locale),FOREIGN KEY(tenant_id,updated_by) REFERENCES gcms_s02.membership(tenant_id,user_id),CHECK(gcms_m4.valid_content(kind,content) IS TRUE));
CREATE INDEX variant_keyset ON gcms_m4.variant(tenant_id,kind,locale,resource_id);
CREATE TABLE gcms_m4.revision(tenant_id text NOT NULL,kind text NOT NULL,resource_id text NOT NULL,locale text NOT NULL,id text NOT NULL DEFAULT gen_random_uuid()::text,version integer NOT NULL,content jsonb NOT NULL,event text NOT NULL CHECK(event IN ('created','saved','restored')),actor_id text NOT NULL,actor_name text NOT NULL,restored_from text,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),PRIMARY KEY(tenant_id,id),UNIQUE(tenant_id,kind,resource_id,locale,version),FOREIGN KEY(tenant_id,kind,resource_id,locale) REFERENCES gcms_m4.variant(tenant_id,kind,resource_id,locale));
CREATE TABLE gcms_m4.publication(tenant_id text NOT NULL,kind text NOT NULL,resource_id text NOT NULL,locale text NOT NULL,id text NOT NULL DEFAULT gen_random_uuid()::text,publication_version integer NOT NULL,draft_version integer NOT NULL,generation integer NOT NULL,content jsonb NOT NULL,site jsonb NOT NULL,reference_pins jsonb NOT NULL,published_by text NOT NULL,published_at timestamptz NOT NULL DEFAULT clock_timestamp(),PRIMARY KEY(tenant_id,id),UNIQUE(tenant_id,kind,resource_id,locale,publication_version),FOREIGN KEY(tenant_id,kind,resource_id,locale,draft_version) REFERENCES gcms_m4.revision(tenant_id,kind,resource_id,locale,version));
ALTER TABLE gcms_m4.variant ADD CONSTRAINT active_publication_fk FOREIGN KEY(tenant_id,active_publication_id) REFERENCES gcms_m4.publication(tenant_id,id);
CREATE TABLE gcms_m4.receipt(tenant_id text NOT NULL,operation_id text NOT NULL CHECK(gcms_m3.uuid(operation_id)),kind text NOT NULL,resource_id text NOT NULL,locale text NOT NULL,actor_id text NOT NULL,command jsonb NOT NULL,result jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),PRIMARY KEY(tenant_id,operation_id),FOREIGN KEY(tenant_id,kind,resource_id,locale) REFERENCES gcms_m4.variant(tenant_id,kind,resource_id,locale));
CREATE TABLE gcms_m4.intent(tenant_id text NOT NULL,kind text NOT NULL,resource_id text NOT NULL,locale text NOT NULL,id text NOT NULL DEFAULT gen_random_uuid()::text,publication_id text,event text NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),PRIMARY KEY(tenant_id,id),FOREIGN KEY(tenant_id,kind,resource_id,locale) REFERENCES gcms_m4.variant(tenant_id,kind,resource_id,locale),FOREIGN KEY(tenant_id,publication_id) REFERENCES gcms_m4.publication(tenant_id,id));
CREATE TABLE gcms_m4.permission(tenant_id text NOT NULL,kind text NOT NULL,resource_id text NOT NULL,locale text NOT NULL,id text NOT NULL DEFAULT gen_random_uuid()::text,revision integer NOT NULL,scope jsonb NOT NULL,scope_key text NOT NULL,evidence_reference text NOT NULL,granted_by text NOT NULL,granted_at timestamptz NOT NULL DEFAULT clock_timestamp(),withdrawn_at timestamptz,withdrawal_reason text,PRIMARY KEY(tenant_id,id),UNIQUE(tenant_id,kind,resource_id,locale,revision,scope_key),FOREIGN KEY(tenant_id,kind,resource_id,locale,revision) REFERENCES gcms_m4.revision(tenant_id,kind,resource_id,locale,version));
DO $$ DECLARE n text;BEGIN FOREACH n IN ARRAY ARRAY['identity','variant','revision','publication','receipt','intent','permission'] LOOP
 EXECUTE format('ALTER TABLE gcms_m4.%I ENABLE ROW LEVEL SECURITY',n);EXECUTE format('ALTER TABLE gcms_m4.%I FORCE ROW LEVEL SECURITY',n);EXECUTE format('CREATE POLICY owner_all ON gcms_m4.%I TO gcms_s02_owner USING(true) WITH CHECK(true)',n);EXECUTE format('CREATE POLICY tenant_read ON gcms_m4.%I FOR SELECT TO gcms_s02_tenant USING(tenant_id=nullif(current_setting(''gcms.tenant_id'',true),'''') AND gcms_s02.has_current_membership(tenant_id))',n);
 END LOOP;FOREACH n IN ARRAY ARRAY['revision','publication','receipt','intent'] LOOP EXECUTE format('CREATE TRIGGER immutable_%I BEFORE UPDATE OR DELETE ON gcms_m4.%I FOR EACH ROW EXECUTE FUNCTION gcms_s02.immutable_publication()',n,n);END LOOP;END $$;
CREATE FUNCTION gcms_m4.assets(k text,c jsonb) RETURNS SETOF jsonb LANGUAGE plpgsql IMMUTABLE SET search_path=pg_catalog AS $$DECLARE s jsonb;a jsonb;BEGIN
 IF k='config' AND c->'logo'<>'null'::jsonb THEN RETURN NEXT (c->'logo')||'{"usage":"logo"}';END IF;
 IF k IN ('home','page','landing') THEN FOR s IN SELECT value FROM jsonb_array_elements(c->'sections') LOOP IF s->>'type'='hero' AND s->'image'<>'null'::jsonb THEN RETURN NEXT (s->'image')||'{"usage":"hero"}';END IF;END LOOP;
 ELSIF k='service' AND c ? 'coverImage' AND c->'coverImage'<>'null'::jsonb THEN RETURN NEXT (c->'coverImage')||'{"usage":"page"}';
 ELSIF gcms_m3.kind(k) THEN FOR a IN SELECT * FROM gcms_m3.asset_refs(c) LOOP RETURN NEXT a||'{"usage":"page"}';END LOOP;END IF;
END $$;
CREATE FUNCTION gcms_m4.refs(k text,c jsonb) RETURNS SETOF jsonb LANGUAGE plpgsql IMMUTABLE SET search_path=pg_catalog AS $$DECLARE s jsonb;r jsonb;BEGIN
 IF k='service' THEN FOR r IN SELECT value FROM jsonb_array_elements(coalesce(c->'contentLinks'->'references','[]')) LOOP RETURN NEXT r||'{"required":false}';END LOOP;
 ELSIF k='promotion' OR gcms_m3.kind(k) THEN FOR r IN SELECT value FROM jsonb_array_elements(c->'references') LOOP RETURN NEXT r||jsonb_build_object('required',k IN ('promotion','price'));END LOOP;
 ELSIF k IN ('home','page','landing') THEN FOR s IN SELECT value FROM jsonb_array_elements(c->'sections') LOOP IF s->'hidden'='true'::jsonb THEN CONTINUE;END IF;
  IF s ? 'references' THEN FOR r IN SELECT value FROM jsonb_array_elements(s->'references') LOOP RETURN NEXT r||jsonb_build_object('required',(s->>'required')::boolean);END LOOP;END IF;
  IF s->>'type'='promotion' THEN RETURN NEXT (s->'reference')||jsonb_build_object('required',(s->>'required')::boolean);END IF;
  IF s->>'type'='consultation' THEN IF s->'promotion'<>'null'::jsonb THEN RETURN NEXT (s->'promotion')||'{"required":true}';END IF;FOR r IN SELECT value FROM jsonb_array_elements((s->'serviceOptions')||(s->'locationOptions')) LOOP RETURN NEXT r||'{"required":true}';END LOOP;END IF;
 END LOOP;END IF;
END $$;
CREATE FUNCTION gcms_m4.path(t text,l text,k text,s text) RETURNS text LANGUAGE sql IMMUTABLE SET search_path=pg_catalog AS $$ SELECT '/'||t||CASE WHEN l='en' THEN '/en' ELSE '' END||CASE k WHEN 'home' THEN '' WHEN 'page' THEN '/'||s WHEN 'landing' THEN '/landing/'||s WHEN 'promotion' THEN '/khuyen-mai/'||s ELSE '/'||gcms_m3.path(k)||'/'||s END $$;
CREATE FUNCTION gcms_m4.identity_slug(t text,k text,r text) RETURNS text LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$ SELECT CASE WHEN k='service' THEN (SELECT slug FROM gcms_s02.service_draft WHERE tenant_id=t AND id=r) WHEN gcms_m3.kind(k) THEN (SELECT slug FROM gcms_m3.resource WHERE tenant_id=t AND id=r AND kind=k) WHEN k='config' AND r=t THEN 'config' ELSE (SELECT slug FROM gcms_m4.identity WHERE tenant_id=t AND kind=k AND id=r) END $$;
CREATE FUNCTION gcms_m4.text_allowed(t text,k text,r text,l text,v integer) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$ SELECT k NOT IN ('case','gallery','testimonial') OR EXISTS(SELECT 1 FROM gcms_m4.permission WHERE tenant_id=t AND kind=k AND resource_id=r AND locale=l AND revision=v AND scope_key='text' AND withdrawn_at IS NULL) $$;
CREATE FUNCTION gcms_m4.asset_allowed(t text,k text,r text,l text,v integer,a jsonb) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$
 SELECT gcms_s07.content_asset_ready(t,a->>'assetId',(a->>'revision')::integer) AND NOT EXISTS(SELECT 1 FROM gcms_m4.permission p WHERE p.tenant_id=t AND p.kind=k AND p.resource_id=r AND p.scope_key='asset:'||(a->>'usage')||':'||(a->>'assetId')||':'||(a->>'revision') AND p.withdrawn_at IS NOT NULL) AND (EXISTS(SELECT 1 FROM gcms_s07.asset x WHERE x.tenant_id=t AND x.id=a->>'assetId' AND x.material_kind='ordinary' AND k NOT IN ('case','gallery','testimonial')) OR EXISTS(SELECT 1 FROM gcms_m4.permission p WHERE p.tenant_id=t AND p.kind=k AND p.resource_id=r AND p.locale=l AND p.revision=v AND p.scope_key='asset:'||(a->>'usage')||':'||(a->>'assetId')||':'||(a->>'revision') AND p.withdrawn_at IS NULL))
$$;
-- A locale variant is adopted only by its first explicit publication. Drafts leave legacy live output intact.
CREATE FUNCTION gcms_m4.pin_refs(t text,k text,r text,l text,c jsonb) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE ref jsonb;v gcms_m4.variant%ROWTYPE;p gcms_m4.publication%ROWTYPE;pins jsonb:='[]';legacy jsonb;BEGIN
 FOR ref IN SELECT * FROM gcms_m4.refs(k,c) LOOP
  IF ref->>'id'=r THEN RAISE EXCEPTION 'Self reference' USING ERRCODE='23514';END IF;
  SELECT * INTO v FROM gcms_m4.variant WHERE tenant_id=t AND kind=ref->>'kind' AND resource_id=ref->>'id' AND locale=l;
  IF v.publication_version>0 THEN
   SELECT * INTO p FROM gcms_m4.publication WHERE tenant_id=t AND id=ref->>'publicationId' AND resource_id=ref->>'id' AND kind=ref->>'kind' AND locale=l AND generation=v.generation;
   IF p.id IS NULL OR v.active_publication_id IS NULL OR NOT gcms_m4.text_allowed(t,p.kind,p.resource_id,l,p.draft_version) THEN RAISE EXCEPTION 'Locale reference unavailable' USING ERRCODE='23514';END IF;
   pins:=pins||jsonb_build_array(ref||jsonb_build_object('locale',l,'generation',v.generation,'legacy',false));
  ELSE
   IF l<>'vi' OR ref->>'kind'='promotion' THEN RAISE EXCEPTION 'Same-language published reference required' USING ERRCODE='23514';END IF;
   legacy:=gcms_m3.pin_refs(t,r,jsonb_build_array(ref-ARRAY['required']));pins:=pins||jsonb_build_array((legacy->0)||jsonb_build_object('required',(ref->>'required')::boolean,'locale','vi','legacy',true));
  END IF;
 END LOOP;IF jsonb_array_length(pins)>250 THEN RAISE EXCEPTION 'Reference graph limit' USING ERRCODE='23514';END IF;RETURN pins;
END $$;
CREATE FUNCTION gcms_m4.command(t text,k text,r text,l text,c jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE d gcms_m4.variant%ROWTYPE;old gcms_m4.receipt%ROWTYPE;h gcms_m4.revision%ROWTYPE;s gcms_s02.site_draft%ROWTYPE;doc jsonb;keys text[];action text:=c->>'type';pins jsonb;pid text;out jsonb;slug_value text;legacy_state jsonb;initial_version integer;a jsonb;scope_key_value text;perm gcms_m4.permission%ROWTYPE;BEGIN
 PERFORM gcms_s05.authorize(t,true);
 IF NOT gcms_m4.kind(k) OR NOT gcms_m4.locale(l) OR NOT gcms_m3.uuid(r) OR NOT gcms_m3.uuid(c->>'operationId') THEN RAISE EXCEPTION 'Invalid command identity' USING ERRCODE='23514';END IF;
 keys:=CASE action WHEN 'create' THEN ARRAY['type','operationId','content'] WHEN 'save' THEN ARRAY['type','operationId','expectedVersion','content'] WHEN 'publish' THEN ARRAY['type','operationId','expectedVersion','expectedPublicationVersion','expectedPublicationRevision','expectedConfigPublicationId'] WHEN 'unpublish' THEN ARRAY['type','operationId','expectedVersion','expectedPublicationRevision'] WHEN 'restore' THEN ARRAY['type','operationId','expectedVersion','sourceRevisionId'] WHEN 'grant' THEN ARRAY['type','operationId','expectedVersion','revision','scope','evidenceReference'] WHEN 'withdraw' THEN ARRAY['type','operationId','expectedVersion','permissionId','reason'] END;
 IF keys IS NULL OR jsonb_typeof(c) IS DISTINCT FROM 'object' OR NOT(c ?& keys) OR (c-keys)<>'{}' OR (action<>'create' AND NOT gcms_m3.version(c->'expectedVersion',true)) THEN RAISE EXCEPTION 'Invalid command shape' USING ERRCODE='23514';END IF;
 IF action IN ('publish','unpublish','grant','withdraw') AND NOT gcms_s02.has_recent_auth() THEN RETURN '{"code":"REAUTH_REQUIRED"}';END IF;
 SELECT * INTO old FROM gcms_m4.receipt WHERE tenant_id=t AND operation_id=c->>'operationId';IF old.operation_id IS NOT NULL THEN IF old.actor_id<>gcms_s02.current_actor() OR old.kind<>k OR old.resource_id<>r OR old.locale<>l OR old.command<>c THEN RAISE EXCEPTION 'Operation conflict' USING ERRCODE='23514';END IF;RETURN old.result||'{"replayed":true}';END IF;
 SELECT * INTO d FROM gcms_m4.variant WHERE tenant_id=t AND kind=k AND resource_id=r AND locale=l FOR UPDATE;
 IF action IN ('create','save') AND d.resource_id IS NULL THEN
  legacy_state:=gcms_m4.legacy_state(t,k,r);initial_version:=coalesce((legacy_state->>'version')::integer,0);IF (action='save' AND (c->>'expectedVersion')::integer<>initial_version) OR (action='create' AND legacy_state IS NOT NULL) THEN RAISE EXCEPTION 'Source version conflict' USING ERRCODE='23514';END IF;
  doc:=c->'content';IF gcms_m4.valid_content(k,doc) IS NOT TRUE THEN RAISE EXCEPTION 'Invalid content' USING ERRCODE='23514';END IF;
  slug_value:=gcms_m4.identity_slug(t,k,r);
  IF k IN ('home','page','landing','promotion') AND slug_value IS NULL THEN INSERT INTO gcms_m4.identity(tenant_id,kind,id,slug) VALUES(t,k,r,doc->>'slug');slug_value:=doc->>'slug';END IF;
  IF slug_value IS NULL OR (k<>'config' AND doc->>'slug' IS DISTINCT FROM slug_value) THEN RAISE EXCEPTION 'Resource identity or slug unavailable' USING ERRCODE='23514';END IF;
  INSERT INTO gcms_m4.variant(tenant_id,kind,resource_id,locale,version,content,legacy_guard,updated_by) VALUES(t,k,r,l,initial_version+1,doc,legacy_state,gcms_s02.current_actor());
 ELSE
  IF d.resource_id IS NULL THEN RETURN '{"code":"NOT_FOUND"}';END IF;
  IF action='create' OR d.version<>(c->>'expectedVersion')::integer THEN RAISE EXCEPTION 'Version conflict' USING ERRCODE='23514';END IF;
  IF action IN ('save','restore') THEN
   IF action='restore' THEN SELECT * INTO h FROM gcms_m4.revision WHERE tenant_id=t AND kind=k AND resource_id=r AND locale=l AND id=c->>'sourceRevisionId';IF h.id IS NULL THEN RAISE EXCEPTION 'Restore scope conflict' USING ERRCODE='23514';END IF;doc:=h.content;ELSE doc:=c->'content';END IF;
   IF gcms_m4.valid_content(k,doc) IS NOT TRUE OR (k<>'config' AND doc->>'slug' IS DISTINCT FROM gcms_m4.identity_slug(t,k,r)) THEN RAISE EXCEPTION 'Content or locked slug conflict' USING ERRCODE='23514';END IF;
   UPDATE gcms_m4.variant SET version=version+1,content=doc,updated_by=gcms_s02.current_actor(),updated_at=clock_timestamp() WHERE tenant_id=t AND kind=k AND resource_id=r AND locale=l;
  ELSIF action='publish' THEN
   IF NOT gcms_m3.version(c->'expectedPublicationVersion',true) OR NOT gcms_m3.version(c->'expectedPublicationRevision',true) OR d.publication_version<>(c->>'expectedPublicationVersion')::integer OR d.publication_revision<>(c->>'expectedPublicationRevision')::integer THEN RAISE EXCEPTION 'Publication conflict' USING ERRCODE='23514';END IF;
   IF d.legacy_guard IS NOT NULL AND d.legacy_guard IS DISTINCT FROM gcms_m4.legacy_state(t,k,r) THEN RAISE EXCEPTION 'Legacy source changed; reload required' USING ERRCODE='23514';END IF;SELECT * INTO s FROM gcms_s02.site_draft WHERE tenant_id=t FOR SHARE;IF s.tenant_id IS NULL OR s.slug IS NULL THEN RAISE EXCEPTION 'Site identity required' USING ERRCODE='23514';END IF;
   IF k<>'config' AND c->'expectedConfigPublicationId' IS DISTINCT FROM coalesce(to_jsonb((SELECT active_publication_id FROM gcms_m4.variant WHERE tenant_id=t AND kind='config' AND resource_id=t AND locale=l)),'null') THEN RAISE EXCEPTION 'Config publication conflict' USING ERRCODE='23514';END IF;
   IF l='en' AND k<>'config' AND NOT EXISTS(SELECT 1 FROM gcms_m4.variant WHERE tenant_id=t AND kind='config' AND resource_id=t AND locale='en' AND active_publication_id IS NOT NULL) THEN RAISE EXCEPTION 'Published EN config required' USING ERRCODE='23514';END IF;IF k='config' AND c->'expectedConfigPublicationId'<>'null'::jsonb THEN RAISE EXCEPTION 'Config command context' USING ERRCODE='23514';END IF;
   IF NOT gcms_m4.text_allowed(t,k,r,l,d.version) THEN RAISE EXCEPTION 'Locale text permission required' USING ERRCODE='23514';END IF;
   FOR a IN SELECT * FROM gcms_m4.assets(k,d.content) LOOP IF NOT gcms_m4.asset_allowed(t,k,r,l,d.version,a) THEN RAISE EXCEPTION 'Scoped media permission required' USING ERRCODE='23514';END IF;END LOOP;
   pins:=gcms_m4.pin_refs(t,k,r,l,d.content);pid:=gen_random_uuid()::text;
   INSERT INTO gcms_m4.publication(tenant_id,kind,resource_id,locale,id,publication_version,draft_version,generation,content,site,reference_pins,published_by) VALUES(t,k,r,l,pid,d.publication_version+1,d.version,d.generation,d.content,jsonb_build_object('name',s.name,'footer',jsonb_build_object('intro',s.footer_intro,'body',s.footer_body)),pins,gcms_s02.current_actor());
   UPDATE gcms_s02.site_draft SET slug_locked=true WHERE tenant_id=t AND NOT slug_locked;UPDATE gcms_m4.variant SET active_publication_id=pid,publication_version=publication_version+1,publication_revision=publication_revision+1 WHERE tenant_id=t AND kind=k AND resource_id=r AND locale=l;
   UPDATE gcms_m4.identity SET slug_locked=true WHERE tenant_id=t AND kind=k AND id=r;UPDATE gcms_s02.site_draft SET slug_locked=true WHERE tenant_id=t AND NOT slug_locked;
   INSERT INTO gcms_m4.intent(tenant_id,kind,resource_id,locale,publication_id,event) VALUES(t,k,r,l,pid,'published');
  ELSIF action='unpublish' THEN
   IF NOT gcms_m3.version(c->'expectedPublicationRevision',true) OR d.publication_revision<>(c->>'expectedPublicationRevision')::integer OR d.active_publication_id IS NULL THEN RAISE EXCEPTION 'Publication conflict' USING ERRCODE='23514';END IF;
   UPDATE gcms_m4.variant SET active_publication_id=NULL,generation=generation+1,publication_revision=publication_revision+1 WHERE tenant_id=t AND kind=k AND resource_id=r AND locale=l;INSERT INTO gcms_m4.intent(tenant_id,kind,resource_id,locale,event) VALUES(t,k,r,l,'unpublished');
  ELSIF action='grant' THEN
   IF c->'revision'<>to_jsonb(d.version) OR NOT gcms_m4.text(c->'evidenceReference',500,true) OR jsonb_typeof(c->'scope') IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'Permission revision conflict' USING ERRCODE='23514';END IF;
   IF c->'scope'='{ "type":"text"}'::jsonb AND k IN ('case','gallery','testimonial') THEN scope_key_value:='text';
   ELSIF c->'scope'->>'type'='asset' AND (c->'scope'-ARRAY['type','assetId','assetRevision','usage'])='{}' AND gcms_m3.uuid(c->'scope'->>'assetId') AND gcms_m3.version(c->'scope'->'assetRevision') AND c->'scope'->>'usage' IN ('logo','hero','page') THEN
    IF NOT EXISTS(SELECT 1 FROM gcms_m4.assets(k,d.content) x WHERE x->>'assetId'=c->'scope'->>'assetId' AND x->'revision'=c->'scope'->'assetRevision' AND x->>'usage'=c->'scope'->>'usage') OR NOT gcms_s07.content_asset_ready(t,c->'scope'->>'assetId',(c->'scope'->>'assetRevision')::integer) THEN RAISE EXCEPTION 'Asset scope conflict' USING ERRCODE='23514';END IF;scope_key_value:='asset:'||(c->'scope'->>'usage')||':'||(c->'scope'->>'assetId')||':'||(c->'scope'->>'assetRevision');
   ELSE RAISE EXCEPTION 'Invalid permission scope' USING ERRCODE='23514';END IF;
   INSERT INTO gcms_m4.permission(tenant_id,kind,resource_id,locale,revision,scope,scope_key,evidence_reference,granted_by) VALUES(t,k,r,l,d.version,c->'scope',scope_key_value,c->>'evidenceReference',gcms_s02.current_actor());
  ELSIF action='withdraw' THEN
   IF NOT gcms_m4.text(c->'reason',500,true) OR NOT gcms_m3.uuid(c->>'permissionId') THEN RAISE EXCEPTION 'Invalid withdrawal' USING ERRCODE='23514';END IF;
   UPDATE gcms_m4.permission SET withdrawn_at=clock_timestamp(),withdrawal_reason=c->>'reason' WHERE tenant_id=t AND kind=k AND resource_id=r AND locale=l AND id=c->>'permissionId' AND withdrawn_at IS NULL RETURNING * INTO perm;IF perm.id IS NULL THEN RAISE EXCEPTION 'Permission unavailable' USING ERRCODE='23514';END IF;
   IF perm.scope_key='text' THEN UPDATE gcms_m4.variant SET active_publication_id=NULL,generation=generation+1,publication_revision=publication_revision+1 WHERE tenant_id=t AND kind=k AND resource_id=r AND locale=l;END IF;
   INSERT INTO gcms_m4.intent(tenant_id,kind,resource_id,locale,event) VALUES(t,k,r,l,'permission.withdrawn');
  END IF;
 END IF;
 IF action IN ('create','save','restore') THEN
  SELECT * INTO d FROM gcms_m4.variant WHERE tenant_id=t AND kind=k AND resource_id=r AND locale=l;
  FOR a IN SELECT * FROM gcms_m4.assets(k,d.content) LOOP IF NOT EXISTS(SELECT 1 FROM gcms_s07.asset WHERE tenant_id=t AND id=a->>'assetId' AND revision>=(a->>'revision')::integer) THEN RAISE EXCEPTION 'Unknown/cross-tenant media' USING ERRCODE='23514';END IF;END LOOP;
  INSERT INTO gcms_m4.revision(tenant_id,kind,resource_id,locale,version,content,event,actor_id,actor_name,restored_from) SELECT t,k,r,l,d.version,d.content,CASE WHEN h.id IS NOT NULL THEN 'restored' WHEN d.version=1 THEN 'created' ELSE 'saved' END,gcms_s02.current_actor(),u.name,h.id FROM gcms_s02_auth."user" u WHERE u.id=gcms_s02.current_actor();
 END IF;
 out:=jsonb_build_object('operationId',c->>'operationId','replayed',false);INSERT INTO gcms_m4.receipt(tenant_id,operation_id,kind,resource_id,locale,actor_id,command,result) VALUES(t,c->>'operationId',k,r,l,gcms_s02.current_actor(),c,out);INSERT INTO gcms_s02.audit_event(id,tenant_id,actor_id,event,target_id) VALUES(gen_random_uuid()::text,t,gcms_s02.current_actor(),'m4.'||action,r);RETURN out;
END $$;
REVOKE ALL ON ALL TABLES IN SCHEMA gcms_m4 FROM PUBLIC;
REVOKE EXECUTE ON ALL FUNCTIONS IN SCHEMA gcms_m4 FROM PUBLIC;
GRANT USAGE ON SCHEMA gcms_m4 TO gcms_s02_tenant;
GRANT SELECT ON ALL TABLES IN SCHEMA gcms_m4 TO gcms_s02_tenant;
GRANT EXECUTE ON FUNCTION gcms_m4.command(text,text,text,text,jsonb) TO gcms_s02_tenant;
